insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954000, 'de300000-0000-4000-a000-000000000102', 940001, 'Pimiento ha hecho su primer nido de burbujas 🫧 Leí que es señal de que está a gusto. ¿Es así o me estoy haciendo ilusiones? #betta', array['/wiki-media/Acuarios/Acuario%20plantado/Especies%20habituales/Peces/Betta_splendens.webp']::text[], 'es', '2026-10-23T06:52:14.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954001, 'de300000-0000-4000-a000-000000000101', 940000, 'Cambio del 30 % hecho y los demasoni ya están otra vez peleando por la misma piedra de siempre. Tienen 40 piedras, pero quieren ESA 😂 #malawi #ciclidos', array['/especies/pseudotropheus-demasoni.webp']::text[], 'es', '2026-10-23T04:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954002, 'de300000-0000-4000-a000-000000000113', 940012, 'El martillo se abrió como nunca después de bajar el flujo de la bomba. A veces menos es más. #reef #lps', array['/wiki-media/Acuarios/Acuario%20marino%20%E2%80%94%20arrecife%20de%20coral%20(reef)/Especies%20habituales/Corales/Euphyllia_ancora.webp']::text[], 'es', '2026-10-23T01:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954003, 'de300000-0000-4000-a000-000000000109', 940008, 'Día 22 con mi primer acuario. Ya nacieron guppys 😱 Nadie me avisó de que pasaba tan rápido. ¿Los separo? #principiantes #guppy', array['/wiki-media/Acuarios/Acuario%20dulce%20tropical%20de%20comunidad/Especies%20habituales/Peces/Poecilia_reticulata.webp']::text[], 'es', '2026-10-22T21:45:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954004, 'de300000-0000-4000-a000-000000000119', 940018, 'ICP reçu : tout est dans les clous sauf l’iode, un peu bas. On corrige doucement. #recifal #sps', array['/wiki-media/Equipamiento/Tests/Tests.webp']::text[], 'fr', '2026-10-22T16:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954005, 'de300000-0000-4000-a000-000000000112', 940011, 'Hojas de catappa nuevas y el agua otra vez color té. Los cardenales salen mucho más cuando el agua está tinta 🍂 #biotopo', array['/wiki-media/Acuarios/Acuario%20de%20discus/Especies%20habituales/Peces/Paracheirodon_axelrodi.webp']::text[], 'es', '2026-10-22T12:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954006, 'de300000-0000-4000-a000-000000000116', 940015, 'Weekly 50 % change done. Nitrates from 40 down to 20. Two FX6s are noisy but worth it. #mbuna #cichlids', array['/especies/pseudotropheus-demasoni.webp']::text[], 'en', '2026-10-22T07:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954007, 'de300000-0000-4000-a000-000000000104', 940003, 'Selección de este mes: me quedo solo con las rojas más intensas para la próxima generación. Las demás van a otro tanque, nadie se queda sin casa 🦐 #gambas #neocaridina', array['/wiki-media/Acuarios/Acuario%20dulce%20tropical%20de%20comunidad/Especies%20habituales/Invertebrados/Neocaridina_davidi.webp']::text[], 'es', '2026-10-22T02:33:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954008, 'de300000-0000-4000-a000-000000000105', null, 'Consejo de alguien que lleva 30 años en esto: la mayoría de los problemas no se arreglan con productos, se arreglan con paciencia y cambios de agua. Lo demás es marketing. #consejos', '{}'::text[], 'es', '2026-10-21T21:45:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954009, 'de300000-0000-4000-a000-000000000118', 940017, 'Die Zitronengrundeln haben sich endlich zwischen den Zoanthus eingelebt. Kleines Becken, große Freude. #nanoriff', array['/especies/gobiodon-citrinus.webp']::text[], 'de', '2026-10-21T16:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954010, 'de300000-0000-4000-a000-000000000110', 940009, 'Con estos 38 °C afuera, el ventilador sobre el acuario es lo único que mantiene los 27 °C. ¿Qué usan ustedes en verano? #monterrey #plantado', array['/wiki-media/Acuarios/Acuario%20de%20discus/Especies%20habituales/Peces/Pterophyllum_scalare.webp']::text[], 'es', '2026-10-21T12:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954011, 'de300000-0000-4000-a000-000000000106', 940005, 'Mis compañeros ya vienen a ver a las rasboras a la hora del café. El nano de oficina es lo mejor que he hecho este año 😄 #nano', array['/especies/boraras-maculatus.webp']::text[], 'es', '2026-10-21T07:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954012, 'de300000-0000-4000-a000-000000000120', 940019, 'Primo cambio d’acqua fatto da sola! Il betta mi ha guardato tutto il tempo come per controllarmi 😅 #betta', array['/wiki-media/Acuarios/Acuario%20plantado/Especies%20habituales/Peces/Betta_splendens.webp']::text[], 'it', '2026-10-21T02:33:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954013, 'de300000-0000-4000-a000-000000000121', 940020, 'Poda da rotala feita. Agora os acarás têm espaço pra nadar de novo. #plantado #acarabandeira', array['/especies/rotala-indica.webp']::text[], 'pt', '2026-10-20T19:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954014, 'de300000-0000-4000-a000-000000000107', 940006, 'Un año sin CO₂ ni abonos y el low-tech sigue creciendo solo. Las criptos han cubierto todo el fondo. Menos esfuerzo, más mirar 🌿 #lowtech #walstad', array['/wiki-media/Acuarios/Acuario%20plantado/Acuario_plantado.webp']::text[], 'es', '2026-10-20T12:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954015, 'de300000-0000-4000-a000-000000000111', 940010, 'El óscar ya reconoce mi cara: cuando entro a la sala se pone a "bailar" contra el vidrio. No me digan que no tienen personalidad. #oscar #ciclidos', array['/especies/astronotus-ocellatus.webp']::text[], 'es', '2026-10-20T04:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954016, 'de300000-0000-4000-a000-000000000117', 940016, 'New Bucephalandra leaf! It only took six weeks 🐌 Buce growth is a lesson in patience. #bucephalandra #planted', array['null']::text[], 'en', '2026-10-19T21:45:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954017, 'de300000-0000-4000-a000-000000000114', 940013, 'Mi hija le puso nombre a los cinco platys y yo no distingo ni a dos 😂 El Ancistrus se llama "Aspiradora". #platy', array['/wiki-media/Acuarios/Acuario%20dulce%20tropical%20de%20comunidad/Especies%20habituales/Peces/Xiphophorus_maculatus.webp']::text[], 'es', '2026-10-19T14:33:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954018, 'de300000-0000-4000-a000-000000000103', 940002, 'El cirujano azul ya come de la pinza. Tres semanas de cuarentena valieron la pena: ni un punto blanco. #marino #cuarentena', array['/wiki-media/Acuarios/Acuario%20marino%20%E2%80%94%20arrecife%20de%20coral%20(reef)/Especies%20habituales/Peces/Paracanthurus_hepatus.webp']::text[], 'es', '2026-10-19T07:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954019, 'de300000-0000-4000-a000-000000000123', 940022, 'Wekelijkse snoei klaar. Een Hollands aquarium is tuinieren onder water: elke straat op de juiste hoogte. #hollandsaquarium', array['/wiki-media/Acuarios/Acuario%20plantado/Acuario_plantado.webp']::text[], 'nl', '2026-10-19T00:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954020, 'de300000-0000-4000-a000-000000000115', 940014, 'First berried CRS of the season 🎉 TDS steady at 150 for two months. Stability is everything with Caridina. #shrimp #caridina', array['/wiki-media/Acuarios/Acuario%20de%20gambas/Especies%20habituales/Invertebrados/Caridina_cantonensis_CRS.webp']::text[], 'en', '2026-10-18T14:33:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954021, 'de300000-0000-4000-a000-000000000122', 940021, 'Rotala wreszcie czerwienieje na górze. Więcej światła i trochę mniej azotanów zrobiło robotę. #akwarystyka #rotala', array['/especies/rotala-indica.webp']::text[], 'pl', '2026-10-18T04:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954022, 'de300000-0000-4000-a000-000000000124', 940023, 'Para quien diga que en Canarias no se puede tener agua fría: 23 °C en pleno octubre con ventilador y mucha aireación. Los ryukin, felices. #goldfish #aguafria', array['/wiki-media/Acuarios/Estanques%20koi/Especies%20habituales/Goldfish%20fancy/Goldfish_ryukin.webp']::text[], 'es', '2026-10-17T16:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954023, 'de300000-0000-4000-a000-000000000108', 940007, 'Huevos de Aphyosemion recogidos de la mopa. Si alguien quiere probar con killis, aviso en el foro cuando eclosionen. #killis', array['/especies/aphyosemion-australe.webp']::text[], 'es', '2026-10-17T07:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954024, 'de300000-0000-4000-a000-000000000101', null, '¿Mbunas o Aulonocaras? Yo los tengo juntos y funciona porque hay mucha roca, pero entiendo a los puristas. ¿Vosotros qué hacéis? #malawi', array['/especies/aulonocara-baenschi.webp']::text[], 'es', '2026-10-16T19:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954025, 'de300000-0000-4000-a000-000000000113', null, 'Recordatorio: antes de comprar un coral, mira qué luz y qué flujo necesita. El 90 % de los corales que se mueren en un reef nuevo es por ponerlos en el sitio equivocado. #reef', array['/wiki-media/Biologia/Corales/Biologia_corales.webp']::text[], 'es', '2026-10-16T04:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954026, 'de300000-0000-4000-a000-000000000112', null, 'Pregunta para los de biotopo: ¿usan solo hojas de catappa o también de roble? Me dijeron que las de roble también sirven. #biotopo', '{}'::text[], 'es', '2026-10-15T12:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954027, 'de300000-0000-4000-a000-000000000105', 940004, 'Pareja de ramirezi limpiando una piedra plana. Si todo va bien, la semana que viene habrá puesta. #ramirezi', array['/especies/mikrogeophagus-ramirezi.webp']::text[], 'es', '2026-10-15T00:09:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954028, 'de300000-0000-4000-a000-000000000102', null, '¿Cuántas veces al día dais de comer al betta? Pimiento me mira con cara de hambre todo el rato y no sé si me está manipulando 🙄 #betta', '{}'::text[], 'es', '2026-10-14T14:33:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954029, 'de300000-0000-4000-a000-000000000119', null, 'Petit rappel : un bac récifal stable vaut mieux qu’un bac parfait. Changer trois paramètres à la fois, c’est ne jamais savoir lequel a marché. #recifal', '{}'::text[], 'fr', '2026-10-13T21:45:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954030, 'de300000-0000-4000-a000-000000000116', null, 'Hot take: overstocking mbuna works only if you overfilter AND do big weekly water changes. Skip either one and it falls apart. #mbuna', '{}'::text[], 'en', '2026-10-13T04:57:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954031, 'de300000-0000-4000-a000-000000000110', null, 'Usé la calculadora de compatibilidad de Tankily antes de meter los tetras ember con los escalares. Me avisó que los escalares adultos pueden comérselos si son muy chicos. Buena alerta 👌 #compatibilidad', '{}'::text[], 'es', '2026-10-12T09:45:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954032, 'de300000-0000-4000-a000-000000000109', null, 'Pregunta de novato: ¿el agua del grifo con anticloro sirve para los cambios o tengo que comprar agua especial? #principiantes', '{}'::text[], 'es', '2026-10-11T07:21:02.992Z');
insert into public.publicaciones (id, usuario_id, tanque_id, contenido, imagenes, idioma, creado_en) overriding system value values (954033, 'de300000-0000-4000-a000-000000000104', null, 'Las gambas no necesitan comida todos los días. Yo les doy tres veces por semana y el resto comen biofilm. Menos comida, menos problemas. #gambas', '{}'::text[], 'es', '2026-10-10T09:45:02.992Z');
