insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955000, 954000, 'de300000-0000-4000-a000-000000000120', 'Sì! Anche il mio lo fa quando è tranquillo. È un buon segno 😊', 'it', '2026-10-23T07:35:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955001, 954000, 'de300000-0000-4000-a000-000000000105', 'Es buena señal, sí. Un betta estresado no se pone a construir. Tienes a Pimiento contento.', 'es', '2026-10-23T08:04:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955002, 954000, 'de300000-0000-4000-a000-000000000102', '@alberto_30anos qué alegría leer esto, ¡gracias!', 'es', '2026-10-23T08:33:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955003, 954001, 'de300000-0000-4000-a000-000000000116', 'Classic demasoni. Rearrange the rocks every few months and they reset the territories.', 'en', '2026-10-23T07:06:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955004, 954001, 'de300000-0000-4000-a000-000000000101', '@mike_mbuna buena idea, lo probaré en el próximo cambio grande.', 'es', '2026-10-23T07:35:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955005, 954002, 'de300000-0000-4000-a000-000000000001', 'Pasa mucho con las Euphyllia: les gusta el flujo suave e indirecto. ¡Qué bonito!', 'es', '2026-10-23T02:04:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955006, 954002, 'de300000-0000-4000-a000-000000000118', 'Wunderschön! Weniger Strömung hat bei meinen Weichkorallen auch geholfen.', 'de', '2026-10-23T02:33:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955007, 954003, 'de300000-0000-4000-a000-000000000007', '¡Bienvenido al mundo guppy, Diego! Si quieres que sobrevivan, pon musgo o plantas flotantes para que se escondan.', 'es', '2026-10-22T23:25:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955008, 954003, 'de300000-0000-4000-a000-000000000114', 'A mí me pasó lo mismo con los platys 😂 Yo puse una paridera unos días.', 'es', '2026-10-22T23:54:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955009, 954003, 'de300000-0000-4000-a000-000000000109', 'Gracias a las dos, voy a poner plantas flotantes. Ya veo que va a haber guppys para toda la CDMX 😅', 'es', '2026-10-23T00:23:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955010, 954004, 'de300000-0000-4000-a000-000000000113', 'El yodo bajo es muy común, nos pasa a todos. Bien por corregir despacio.', 'es', '2026-10-22T17:40:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955011, 954004, 'de300000-0000-4000-a000-000000000119', '@felipe_reefcl merci ! Toujours doucement en récifal.', 'fr', '2026-10-22T18:09:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955012, 954005, 'de300000-0000-4000-a000-000000000108', 'Qué buen biotopo, Camila. Las catappa también ayudan a que los peces estén menos estresados.', 'es', '2026-10-22T13:49:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955013, 954005, 'de300000-0000-4000-a000-000000000105', 'Los cardenales en agua tinta son otro pez. Muy bien montado.', 'es', '2026-10-22T14:18:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955014, 954006, 'de300000-0000-4000-a000-000000000101', 'Same here, big water changes are the secret with Malawi.', 'es', '2026-10-22T09:59:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955015, 954007, 'de300000-0000-4000-a000-000000000115', 'Love seeing selective breeding done right! Culling to another tank is the way.', 'en', '2026-10-22T03:16:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955016, 954007, 'de300000-0000-4000-a000-000000000015', 'Piękne czerwone! Selekcja to podstawa.', 'pl', '2026-10-22T03:45:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955017, 954008, 'de300000-0000-4000-a000-000000000003', 'Me lo apunto en grande. Yo al principio compraba un producto para cada cosa 🙈', 'es', '2026-10-21T23:25:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955018, 954008, 'de300000-0000-4000-a000-000000000002', 'Cuánta razón. Los cambios de agua arreglan más que cualquier botella.', 'es', '2026-10-21T23:54:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955019, 954008, 'de300000-0000-4000-a000-000000000109', 'Justo lo que necesitaba leer esta semana.', 'es', '2026-10-22T00:23:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955020, 954009, 'de300000-0000-4000-a000-000000000008', 'Qué lindos los gobios limón entre los zoas.', 'es', '2026-10-21T17:40:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955021, 954010, 'de300000-0000-4000-a000-000000000111', 'En Córdoba también sufrimos el verano. Ventilador y bajar la luz un par de horas.', 'es', '2026-10-21T13:21:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955022, 954010, 'de300000-0000-4000-a000-000000000121', 'Aqui em BH uso ventoinha também. E tampa aberta à noite.', 'pt', '2026-10-21T13:49:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955023, 954011, 'de300000-0000-4000-a000-000000000117', 'Office nano club! Mine is on my desk too 😄', 'en', '2026-10-21T09:30:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955024, 954011, 'de300000-0000-4000-a000-000000000106', '@olivia_scapes ¡somos un club! 😂', 'es', '2026-10-21T09:59:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955025, 954012, 'de300000-0000-4000-a000-000000000102', 'Brava Giulia! Il mio fa lo stesso, controlla tutto 😂', 'es', '2026-10-21T03:16:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955026, 954013, 'de300000-0000-4000-a000-000000000110', 'Se ve precioso. Yo también tengo que podar la rotala, se me sale del agua.', 'es', '2026-10-20T20:33:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955027, 954014, 'de300000-0000-4000-a000-000000000002', 'Grande el low-tech. La gente subestima lo bien que funciona con plantas lentas.', 'es', '2026-10-20T13:49:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955028, 954014, 'de300000-0000-4000-a000-000000000107', '@dani_plantados ¡y gasto cero en CO₂!', 'es', '2026-10-20T14:18:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955029, 954015, 'de300000-0000-4000-a000-000000000116', 'Oscars are wet pets. Totally agree.', 'en', '2026-10-20T07:35:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955030, 954015, 'de300000-0000-4000-a000-000000000105', 'Los óscar son los perros del acuario, sin duda.', 'es', '2026-10-20T05:40:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955031, 954016, 'de300000-0000-4000-a000-000000000010', 'Bucephalandra lehrt Geduld. Sehr schön!', 'de', '2026-10-19T22:57:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955032, 954017, 'de300000-0000-4000-a000-000000000109', 'Aspiradora es el mejor nombre 😂', 'es', '2026-10-19T16:13:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955033, 954018, 'de300000-0000-4000-a000-000000000009', 'Quarantine wins again. Great job!', 'en', '2026-10-19T09:30:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955034, 954018, 'de300000-0000-4000-a000-000000000001', 'Así se hace. Cuarentena siempre, aunque cueste.', 'es', '2026-10-19T09:59:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955035, 954019, 'de300000-0000-4000-a000-000000000010', 'Ein echtes Hollands Aquarium, toll gepflegt.', 'de', '2026-10-19T00:52:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955036, 954020, 'de300000-0000-4000-a000-000000000012', 'Félicitations ! La stabilité, toujours la stabilité.', 'fr', '2026-10-18T15:45:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955037, 954020, 'de300000-0000-4000-a000-000000000104', 'Qué maravilla, Emily. Las CRS son mi próximo reto.', 'es', '2026-10-18T16:13:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955038, 954021, 'de300000-0000-4000-a000-000000000123', 'Mooi rood! Meer licht helpt altijd bij rotala.', 'nl', '2026-10-18T07:06:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955039, 954022, 'de300000-0000-4000-a000-000000000006', 'Muy bien, Inés. Lo importante es la oxigenación, más que el número exacto.', 'es', '2026-10-17T19:35:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955040, 954022, 'de300000-0000-4000-a000-000000000005', 'Me encanta ver agua fría en Canarias 😄', 'es', '2026-10-17T17:40:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955041, 954023, 'de300000-0000-4000-a000-000000000112', '¡Yo me apunto! Siempre quise probar con killis.', 'es', '2026-10-17T08:33:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955042, 954024, 'de300000-0000-4000-a000-000000000116', 'Mixing works if you have enough rock and the right females ratio. Purists will hate us anyway 😂', 'en', '2026-10-16T21:01:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955043, 954024, 'de300000-0000-4000-a000-000000000105', 'Si funciona en tu tanque, funciona. Pero vigila la alimentación: los mbunas son herbívoros y los aulonocaras no.', 'es', '2026-10-16T21:30:38.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955044, 954025, 'de300000-0000-4000-a000-000000000103', 'Gran consejo. Yo puse una Euphyllia en pleno chorro de la bomba y casi la pierdo.', 'es', '2026-10-16T07:35:26.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955045, 954026, 'de300000-0000-4000-a000-000000000108', 'Yo uso catappa y también roble y haya bien secas. Funcionan.', 'es', '2026-10-15T12:52:14.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955046, 954027, 'de300000-0000-4000-a000-000000000108', 'Que haya suerte con la puesta 🤞', 'es', '2026-10-15T01:21:02.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955047, 954028, 'de300000-0000-4000-a000-000000000105', 'Una vez al día, una cantidad que se coma en un minuto, y un día de ayuno a la semana. Te está manipulando 😂', 'es', '2026-10-14T16:13:50.992Z');
insert into public.comentarios (id, publicacion_id, usuario_id, contenido, idioma, creado_en) overriding system value values (955048, 954028, 'de300000-0000-4000-a000-000000000120', 'Anche il mio! Sono dei piccoli attori 😂', 'it', '2026-10-14T16:42:38.992Z');
