insert into public.foro_hilos (id, categoria, usuario_id, tanque_id, titulo, contenido, idioma, creado_en, ultima_actividad) overriding system value values (956000, 'principiantes', 'de300000-0000-4000-a000-000000000109', 940008, 'Nitritos altos a las tres semanas: ¿es normal?', 'Mi acuario de 75 l lleva tres semanas. Ayer medí nitritos en 0,5 y amonio en 0,25. Ya tengo guppys. ¿Hago cambios de agua?', 'es', '2026-10-22T04:57:02.992Z', '2026-10-22T04:57:02.992Z');
insert into public.foro_respuestas (id, hilo_id, usuario_id, contenido, idioma, creado_en) overriding system value values (957000, 956000, 'de300000-0000-4000-a000-000000000105', 'Sí: estás en mitad del ciclado con peces dentro. Cambios del 25-30 % cada dos días hasta que nitritos y amonio estén a cero, y come poco.', 'es', '2026-10-22T06:52:14.992Z');
