insert into public.foro_hilos (id, categoria, usuario_id, tanque_id, titulo, contenido, idioma, creado_en, ultima_actividad) overriding system value values (956001, 'ciclidos', 'de300000-0000-4000-a000-000000000101', 940000, '¿Mezclar mbunas y Aulonocaras? Debate', 'Lo dejo abierto porque cada uno dice una cosa. ¿Habéis tenido mbunas con Aulonocaras sin problemas? ¿Con qué litros?', 'es', '2026-10-20T00:09:02.992Z', '2026-10-20T00:09:02.992Z');
insert into public.foro_respuestas (id, hilo_id, usuario_id, contenido, idioma, creado_en) overriding system value values (957003, 956001, 'de300000-0000-4000-a000-000000000116', 'I kept them together in 125 gal for years. Works with lots of rock and feeding a spirulina-based food for everyone.', 'en', '2026-10-20T02:04:14.992Z');
